/**
 * The Boundary
 * ------------
 * The man and woman dwell freely in the garden, permitted every fruit except the tree of the knowledge of good and evil. Stage: the garden's heart, one broad tree set apart in a circle of light; the couple walking away from it; abundance everywhere, one still point of restraint.
 *
 * Palette 0x8b2500 → 0x3d1200 · light: fire · hero: tree
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./adam-kit.js.
 */

import { THREE, createScene, tent, oak, tree, well, person, birds } from './adam-kit.js';

const BG = 0x8b2500;
const GROUND = 0x1a0700;

export function build(group) {
    const W = createScene(group, { seed: 3993558943, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — fire */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x1a0700, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents */
    tent(W, group, 29.6, 0, -19.5, 1.27, 0xc8b088, W.r() * 6);
    tent(W, group, 9.6, 0, -5.3, 1.19, 0xd8c8a0, W.r() * 6);
    tent(W, group, -11.9, 0, -17.8, 1.39, 0xc8b088, W.r() * 6);

    /* trees: broadleaf shade */
    oak(W, group, 43.1, 0, -8.8, 1.15, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -15.1, 0, -59.6, 1.33, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -28.6, 0, -17.8, 1.37, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 63.7, 0, -6.7, 1.22, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    tree(W, group, 3.9, 0, -8.4, 1.1);

    /* garden: shade trees around a well */
    well(W, group, -0.2, 0, -0.4, 1.1);

    /* hero: the great tree */
    oak(W, group, 0, 0, 0, 1.7, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    W.disc([0, 8, -16], 9, 0xb53000, 0.25);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8b2500, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: -0.47, s: 1.06 });
    person(W, group, [4.5, 0, 6], { robe: 0x3d1200, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.29, s: 1.03 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
